# Let's solve the knight's tour problem on a 5x5 board
# We'll use backtracking with constraint propagation

# First, let's map out all possible knight moves on a 5x5 board
n = 5
cells = n * n

# Precompute knight moves
moves = {}
for r in range(n):
    for c in range(n):
        cell = r * n + c
        neighbors = []
        for dr, dc in [(1,2),(2,1),(2,-1),(1,-2),(-1,-2),(-2,-1),(-2,1),(-1,2)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                neighbors.append(nr * n + nc)
        moves[cell] = neighbors

# Fixed assignments: step -> cell
fixed = {3: 23, 4: 16, 5: 5, 15: 15, 22: 24}
# Also step 0 must be cell 0
fixed[0] = 0

print("Fixed assignments:", fixed)
print("Moves from each cell:")
for cell in range(cells):
    print(f"  {cell}: {moves[cell]}")

# Let's check if the fixed assignments are consistent with knight moves
for step, cell in fixed.items():
    if step > 0:
        prev_step = step - 1
        if prev_step in fixed:
            prev_cell = fixed[prev_step]
            if cell not in moves[prev_cell]:
                print(f"INCONSISTENT: step {prev_step} ({prev_cell}) -> step {step} ({cell}) is not a knight move!")
    if step < cells - 1:
        next_step = step + 1
        if next_step in fixed:
            next_cell = fixed[next_step]
            if next_cell not in moves[cell]:
                print(f"INCONSISTENT: step {step} ({cell}) -> step {next_step} ({next_cell}) is not a knight move!")

# Check for duplicate cells
cells_used = list(fixed.values())
if len(cells_used) != len(set(cells_used)):
    print("INCONSISTENT: duplicate cells in fixed assignments!")
else:
    print("No duplicates in fixed assignments.")
